# Create another variant - what if we need to rotate and then swap colors?
def apply_transformation(grid, op):
    """Apply transformation operation"""
    H = len(grid)
    W = len(grid[0])

    result = [row[:] for row in grid]

    if op == 'swap':
        result = [[6 if v == 9 else 9 for v in row] for row in result]
    elif op == 'transpose':
        return list(zip(*result))
    elif op == 'hflip':
        result = [row[::-1] for row in result]
    elif op == 'vflip':
        result = result[::-1]
    elif op == 'rot180':
        result = [row[::-1] for row in result][::-1]

    return result

